    let mut score = post_residual as f64;

    // 1. Aggressive Best-Fit Penalty: 
    // We heavily penalize large post_residuals to keep bins tight, 
    // but we scale this penalty by the number of fitting bins to allow 
    // more flexibility when we have many choices.
    score += (post_residual as f64).powf(1.5) / (fitting_bins_count as f64 + 1.0);

    // 2. Lookahead Synergy:
    // If the post_residual is a near-perfect fit for the next item, reward it.
    // We specifically look for post_residual == next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 2.5;

        // If post_residual is too small to fit the next item, penalize if 
        // we have other bins that could potentially accommodate the next item better.
        if post_residual < next_item_size {
            score += 15.0;
        }
    }

    // 3. Mean Residual Balancing:
    // Avoid creating bins that are significantly "emptier" than the average open bin.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 4. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty 
    // relative to the progress of the stream to discourage opening new bins early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        // The cost to open a new bin increases as we approach the end of the stream.
        score += 40.0 + (progress * 30.0);

        // If we have very few open bins, opening a new one is less penalized.
        score -= (open_bins_count as f64) * 2.0;
    }

    // 5. Last Chance Logic:
    // If this is the only bin that can fit the item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

