    // Lower residual is better, but we penalize "unusable" small gaps (1-8).
    let mut score = post_residual as f64 * 0.92;

    // 1. Fragmentation Control (The "Dead-Zone" Penalty)
    // Small residuals that are too small to hold common items are highly penalized.
    if post_residual > 0 && post_residual <= 8 {
        score += 24.0 - (post_residual as f64 * 1.5);
    } else if post_residual > 8 && post_residual < 20 {
        score += 5.0;
    }

    // 2. Lookahead Integration:
    // If next_item_size is predicted, penalize bins that fail to fit it, 
    // but reward bins that become "perfect fits" (residual 0) or "near-perfect" (residual < 5).
    if next_item_size > post_residual {
        score += (next_item_size - post_residual) as f64 * 1.25;
    } else if next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.15;
    }

    // 3. Bin Creation Logic (The "Empty Bin" Decision)
    if bin_residual == bin_capacity {
        // Heavy penalty for opening new bins if we have many fitting options.
        // Use open_bins_count and mean_residual to regulate the "spread".
        let base_new_bin_penalty = 45.0 + (mean_residual * 1.8) + (open_bins_count as f64 * 0.95);
        score += base_new_bin_penalty + (fitting_bins_count as f64).powf(1.35) * 14.0;
    } else {
        // 4. Consolidation Incentives:
        // Prioritize filling bins that are nearly full to reduce active bin count.
        if bin_residual < 15 {
            score -= 22.0 * (1.0 - (bin_residual as f64 / 15.0));
        }
        // If we only have one option that fits, don't over-calculate, just take it.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    // 5. Temporal Pressure & Distribution Bias:
    // Increase compaction pressure as we approach the end of the stream.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 12.0;

    // 6. Harmonic Alignment:
    // Favor residuals that are multiples of 20 (common divisor for item sizes up to 100).
    if post_residual > 0 && post_residual % 20 == 0 {
        score -= 12.0;
    }

    // 7. Density Overflow Prevention:
    // If open_bins_count is too high, aggressively force bin reuse.
    if open_bins_count > 15 && bin_residual != bin_capacity {
        score -= (open_bins_count as f64) * 0.5;
    }

    score
}

