pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit).
    // Penalize large post_residuals quadratically to avoid fragmentation.
    let mut score = post * post;

    // Lookahead logic: If the next item is large, prioritize keeping space open.
    // If next_item_size is 0, we are near the end, so prioritize filling bins tightly.
    if next_item_size > 0 {
        let fit_next = (bin_residual - item_size) >= next_item_size;
        if !fit_next {
            // Penalize placements that block the next item from fitting in this bin.
            score += (next_item_size as f64) * 50.0;
        }
    }

    // Dynamic density control: 
    // As the stream progresses, discourage opening new bins unless the fit is excellent.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // Penalize opening a new bin proportional to the current average waste.
        // We want to open a new bin only if the current average waste is very high.
        score = mean_residual * 2.5 * (1.0 - progress * 0.5);
    } else {
        // Reward bins that have a residual close to the mean, 
        // effectively clustering similar-sized items.
        let deviation = (post - mean_residual).abs();
        score += deviation * 2.0;

        // If this is the only bin that can fit the item, favor it heavily to avoid wasting a new bin.
        if fitting_bins_count == 1 {
            score -= 1000.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Reward perfect fits (Best Fit strategy)
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2. Penalty for creating "dead zones" (small residuals that cannot fit future items)
    // If the post_residual is smaller than the minimum expected item size (approx 10), it's risky.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // 3. Lookahead Matching: Reward placing items such that the next item fits into the resulting residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // High reward for keeping the bin capable of taking the next item
            score -= 150.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // Penalty for splitting a space that could have been useful for the next item
            score += 100.0;
        }
    }

    // 4. Global balance: If this is the only bin that fits the item, prioritize it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // 5. New Bin logic: Only open a new bin if the current mean_residual is very low (bins are full)
    // or if the current bin's post_residual is significantly worse than the existing mean.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 1000.0; // Discourage opening new bins if existing ones have space
        } else {
            score += 50.0; // Base cost to open a new bin
        }
    }

    // 6. Progress factor: Be more aggressive in filling bins as we approach the end of the stream
    let progress = step_index as f64 / total_items as f64;
    score += progress * 50.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Logic:
    // 1. Base cost is the remaining space (post_residual). Smaller is better (Best Fit).
    // 2. Penalty for creating "dead space": If post_residual is small but > 0, it's often better to have 0.
    // 3. Lookahead: If next_item fits in the current post_residual, prioritize this bin.
    // 4. Global state: If we are late in the stream, be more aggressive about filling bins (Best Fit).
    // 5. New bin logic: High penalty for opening a new bin unless the fit is perfect or we have no choice.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    let mut score = post_residual as f64;

    // Penalty for leaving small, unusable gaps (1..9)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead: If the next item fits in the space left by this item, reward this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // Dynamic threshold: As the stream progresses, favor packing tighter to minimize open bins
    if fitting_bins_count > 0 {
        score += (open_bins_count as f64) * 0.5 * progress;
    }

    // New bin penalty: Heavily discourage opening new bins unless necessary
    if is_new_bin {
        if fitting_bins_count == 0 {
            // No choice, must open new bin
            score = 10.0; 
        } else {
            // We have options, penalize new bin creation
            score = 100.0 - (progress * 20.0);
        }
    }

    // Global state adjustment: If mean residual is high, we have too many half-empty bins.
    // Favor bins that reduce the mean residual (those with smaller residuals).
    if mean_residual > (bin_capacity as f64 * 0.4) {
        score += (post_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Harmonic classes logic: prioritize filling bins to specific "harmonic" fractions
    // that leave room for likely next items, penalizing "dead zones" (e.g., 1-9 residual).

    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (small residuals that are unlikely to fit future items).
    // If post_residual is small but > 0, it's often better to open a new bin or pick a better fit.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 - (post_residual as f64 * 4.5);
    }

    // 2. Lookahead optimization: If next_item_size exists, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that have high probability of fitting the next item.
            score -= 20.0;
        } else {
            // Penalize bins that block the next item from fitting.
            score += 15.0;
        }
    }

    // 3. Harmonic balance: Penalize bins that are "almost full" but not quite, 
    // relative to the mean residual of current bins.
    if (post_residual as f64) < mean_residual * 0.5 {
        score -= 5.0;
    }

    // 4. Threshold for opening new bins: 
    // If this is a new bin (bin_residual == bin_capacity), set a threshold cost.
    // We only open a new bin if the current fit is extremely poor (post_residual is high).
    if bin_residual == bin_capacity {
        // High base cost for new bin to favor existing bins.
        score = 65.0; 

        // If we have very few bins open, opening a new one is cheaper.
        score -= (open_bins_count as f64) * 2.0;

        // If no existing bins can fit the item, lower the cost to open a new one.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // 5. Progression scaling: As we approach the end of the stream, prioritize tightness.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base score: Prioritize tighter post_residual for Best-Fit behavior.
    // Increased weight on post_residual to drive packing density.
    let mut score = post_residual as f64 * 1.15;

    // 1. Fragmentation Control:
    // Penalize gaps that are too small to be useful (dead-zones) while rewarding near-perfect fits.
    if post_residual > 0 {
        if post_residual < 22 {
            score += 28.0 - (post_residual as f64 * 1.1);
        }
        // Lookahead: Penalize bins that cannot fit the next item if they aren't near-full.
        // Penalty is sensitive to the gap size relative to next_item_size.
        if next_item_size > post_residual && post_residual > 6 {
            score += (next_item_size - post_residual) as f64 * 2.85;
        }
    }

    // 2. Adaptive New Bin Logic:
    if bin_residual == bin_capacity {
        // Higher base cost for new bin to favor consolidation.
        // Penalty scales with mean_residual and open_bins_count.
        score += (mean_residual * 3.2) + (open_bins_count as f64 * 2.1);

        // Non-linear penalty based on how many existing bins can fit the item.
        // If fitting_bins_count > 0, opening a new bin is heavily discouraged.
        score += (fitting_bins_count as f64).powf(1.6) * 22.0;
    } else {
        // 3. Consolidation:
        // Prioritize bins that are nearly full (residual < 12) to minimize the count of active bins.
        if fitting_bins_count == 1 {
            score -= 52.0;
        }
        if bin_residual < 12 {
            score -= 32.0;
        }
        // Reward bins that become "perfect" fits (0 residual) or near-perfect.
        if post_residual == 0 {
            score -= 42.0;
        }
    }

    // 4. Temporal Pressure:
    // Increase pressure to consolidate as the stream nears the end to flush out open bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 22.0;

    // 5. Residual Alignment (Distribution Sensitivity):
    // Favor residuals that align with common item size distributions (25, 50, 75).
    if post_residual > 0 {
        if post_residual % 25 == 0 { score -= 18.0; }
        else if post_residual % 20 == 0 { score -= 12.0; }
    }

    // 6. Dynamic Scaling:
    // If we have many open bins, aggressively penalize opening a new one to force recycling.
    if bin_residual == bin_capacity && open_bins_count > 5 {
        score += (open_bins_count as f64) * 5.5;
    }

    // 7. Efficiency floor:
    // Penalize bins that result in high residual (wasted space) to keep the packing tight.
    // Increased penalty to prevent drift in average residual.
    if post_residual > (bin_capacity / 2) {
        score += (post_residual as f64) * 0.85;
    }

    score
